describe('Language Preference Setting in Profile', () => {
  beforeEach(() => {
    cy.visit('/profile/settings');
  });

  it('should successfully set language preference to English', () => {
    // Verify profile settings page is loaded
    cy.get('[data-testid="profile-settings-page"]').should('be.visible');
    cy.get('[data-testid="language-label"]').should('contain', 'Language');

    // Verify current language is displayed
    cy.get('[data-testid="current-language-display"]').should('contain', 'Spanish');

    // Open language dropdown
    cy.get('[data-testid="language-dropdown-button"]').click();

    // Verify language options are visible
    cy.get('[data-testid="language-option-en"]').should('be.visible');
    cy.get('[data-testid="language-option-es"]').should('be.visible');
    cy.get('[data-testid="language-option-fr"]').should('be.visible');

    // Select English
    cy.get('[data-testid="language-option-en"]').click();

    // Verify language selection is updated
    cy.get('[data-testid="current-language-display"]').should('contain', 'English');

    // Click save button
    cy.get('[data-testid="save-settings-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Settings saved successfully');

    // Verify page redirects or refreshes
    cy.url().should('include', '/profile/settings');
  });

  it('should handle invalid language selection and display error message', () => {
    // Verify profile settings page is loaded
    cy.get('[data-testid="profile-settings-page"]').should('be.visible');

    // Open language dropdown
    cy.get('[data-testid="language-dropdown-button"]').click();

    // Attempt to select an invalid option (e.g., a non-existent language)
    cy.get('[data-testid="language-option-invalid"]').should('not.exist');

    // Verify error message appears when trying to save without valid selection
    cy.get('[data-testid="save-settings-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Please select a valid language');

    // Verify language selection did not change
    cy.get('[data-testid="current-language-display"]').should('contain', 'Spanish');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify user can still interact with other settings
    cy.get('[data-testid="email-input"]').should('be.visible');
  });
});
